\set ON_ERROR_STOP on
begin;
create function pg_temp.ok(p boolean,msg text) returns void language plpgsql as $$begin if p is distinct from true then raise exception 'ASSERT: %',msg;end if;end$$;
create function pg_temp.reject(q text,code text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'EXPECTED REJECTION: %',code;end$$;
insert into auth.users(id,email) values('a2230000-0000-4000-8000-000000000001','owner@example.test'),('a2230000-0000-4000-8000-000000000002','private-login-canary@example.test'),('a2230000-0000-4000-8000-000000000003','staff@example.test'),('a2230000-0000-4000-8000-000000000004','admin@example.test');
insert into public.tenants(id,name,slug,timezone,currency) values('a2230000-0000-4000-8000-000000000010','A','snapshot-a','UTC','USD'),('b2230000-0000-4000-8000-000000000010','B','snapshot-b','UTC','USD');
insert into public.tenant_members values('a2230000-0000-4000-8000-000000000010','a2230000-0000-4000-8000-000000000001','BUSINESS_OWNER',now()),('a2230000-0000-4000-8000-000000000010','a2230000-0000-4000-8000-000000000003','BUSINESS_STAFF',now());
insert into public.platform_admins(user_id) values('a2230000-0000-4000-8000-000000000004');
create function pg_temp.snapshot() returns jsonb language sql as $$select public.owner_roster_snapshot('a2230000-0000-4000-8000-000000000001','a2230000-0000-4000-8000-000000000010')$$;
select pg_temp.reject('select pg_temp.snapshot()','P0002');
select pg_temp.ok(not exists(select 1 from public.worker_roster_state),'GET never provisions');
select public.roster_provision('a2230000-0000-4000-8000-000000000001','a2230000-0000-4000-8000-000000000010');
select pg_temp.ok(pg_temp.snapshot()='{"rosterVersion":1,"workers":[],"crews":[],"eligibility":[],"shifts":[],"services":[]}'::jsonb,'complete empty DTO');
set local role service_role;
select pg_temp.reject($q$select public.owner_roster_snapshot('a2230000-0000-4000-8000-000000000003','a2230000-0000-4000-8000-000000000010')$q$,'42501');
select pg_temp.reject($q$select public.owner_roster_snapshot('a2230000-0000-4000-8000-000000000004','a2230000-0000-4000-8000-000000000010')$q$,'42501');
select pg_temp.reject($q$select public.owner_roster_snapshot('a2230000-0000-4000-8000-000000000002','a2230000-0000-4000-8000-000000000010')$q$,'42501');
select pg_temp.reject($q$select public.owner_roster_snapshot('a2230000-0000-4000-8000-000000000001','b2230000-0000-4000-8000-000000000010')$q$,'42501');
reset role;
-- Direct fixture data is under the roster fence; application raw writes remain revoked.
select version from public.worker_roster_state where tenant_id='a2230000-0000-4000-8000-000000000010' for update;
insert into public.workers(id,tenant_id,display_name,active) values('a2230000-0000-4000-8000-000000000030','a2230000-0000-4000-8000-000000000010',repeat(chr(128512),160),false);
insert into public.worker_access(tenant_id,user_id,worker_id,active) values('a2230000-0000-4000-8000-000000000010','a2230000-0000-4000-8000-000000000002','a2230000-0000-4000-8000-000000000030',true);
insert into public.crews(id,tenant_id,name,active) values('a2230000-0000-4000-8000-000000000040','a2230000-0000-4000-8000-000000000010',repeat(chr(128512),160),false);
insert into public.crew_members values('a2230000-0000-4000-8000-000000000010','a2230000-0000-4000-8000-000000000040','a2230000-0000-4000-8000-000000000030');
insert into public.services(id,tenant_id,name,archetype,currency,base_price,active) values('a2230000-0000-4000-8000-000000000020','a2230000-0000-4000-8000-000000000010','Inactive service','simple','USD',0,false);
insert into public.service_worker_eligibility values('a2230000-0000-4000-8000-000000000010','a2230000-0000-4000-8000-000000000020','a2230000-0000-4000-8000-000000000030',false);
insert into public.worker_shifts(id,tenant_id,worker_id,kind,starts_at,ends_at,source_time_zone,active) values('a2230000-0000-4000-8000-000000000050','a2230000-0000-4000-8000-000000000010','a2230000-0000-4000-8000-000000000030','blocked','2035-01-01T10:00:00.123456Z','2035-01-01T10:00:00.123457Z','UTC',false);
select pg_temp.ok(pg_temp.snapshot()->'workers'->0->>'displayName'=repeat(chr(128512),160),'160 Unicode codepoints preserved');
select pg_temp.ok(pg_temp.snapshot()->'crews'->0->'workerIds'='["a2230000-0000-4000-8000-000000000030"]' and pg_temp.snapshot()->'services'->0->'active'='false' and pg_temp.snapshot()->'shifts'->0->>'kind'='blocked','inactive references and blocked shifts included');
set local timezone='Pacific/Auckland';
select pg_temp.ok(pg_temp.snapshot()->'shifts'->0->>'startsAt'='2035-01-01T10:00:00.123456Z' and pg_temp.snapshot()->'shifts'->0->>'endsAt'='2035-01-01T10:00:00.123457Z','UTC microseconds unaffected by session timezone');
select pg_temp.ok(position('private-login-canary' in pg_temp.snapshot()::text)=0 and position('a2230000-0000-4000-8000-000000000002' in pg_temp.snapshot()::text)=0 and not pg_temp.snapshot()?'worker_access','private bridge excluded');
savepoint time_domain;
update public.worker_shifts set starts_at='10000-01-01T00:00Z',ends_at='10000-01-01T01:00Z';select pg_temp.reject('select pg_temp.snapshot()','22008');
rollback to time_domain;
savepoint large_label;
update public.services set name=repeat('x',4096);select pg_temp.ok(length(pg_temp.snapshot()->'services'->0->>'name')=4096,'per-label byte boundary');
update public.services set name=repeat('x',4097);select pg_temp.reject('select pg_temp.snapshot()','54000');
update public.services set name=repeat('x',1000000);select pg_temp.reject('select pg_temp.snapshot()','54000');
rollback to large_label;
-- Remove base fixtures to test complete cardinality boundaries independently.
delete from public.worker_shifts;delete from public.service_worker_eligibility;delete from public.crew_members;delete from public.worker_access;delete from public.workers;delete from public.crews;delete from public.services;
create function pg_temp.seed_workers(n integer) returns void language sql as $$insert into public.workers(id,tenant_id,display_name,active) select gen_random_uuid(),'a2230000-0000-4000-8000-000000000010','W',false from generate_series(1,n)$$;
create function pg_temp.seed_crews(n integer) returns void language sql as $$insert into public.crews(id,tenant_id,name,active) select gen_random_uuid(),'a2230000-0000-4000-8000-000000000010','C',false from generate_series(1,n)$$;
create function pg_temp.seed_services(n integer,label text default 'S') returns void language sql as $$insert into public.services(id,tenant_id,name,archetype,currency,base_price,active) select gen_random_uuid(),'a2230000-0000-4000-8000-000000000010',label,'simple','USD',0,false from generate_series(1,n)$$;
savepoint worker_max;
select pg_temp.seed_workers(100);select pg_temp.ok(jsonb_array_length(pg_temp.snapshot()->'workers')=100,'worker max includes inactive');select pg_temp.seed_workers(1);select pg_temp.reject('select pg_temp.snapshot()','54000');rollback to worker_max;
savepoint crew_max;
select pg_temp.seed_crews(50);select pg_temp.ok(jsonb_array_length(pg_temp.snapshot()->'crews')=50,'crew max');select pg_temp.seed_crews(1);select pg_temp.reject('select pg_temp.snapshot()','54000');rollback to crew_max;
savepoint service_max;
select pg_temp.seed_services(100);select pg_temp.ok(jsonb_array_length(pg_temp.snapshot()->'services')=100,'service max');select pg_temp.seed_services(1);select pg_temp.reject('select pg_temp.snapshot()','54000');rollback to service_max;
savepoint membership_max;
select pg_temp.seed_workers(100);select pg_temp.seed_crews(6);
insert into public.crew_members select 'a2230000-0000-4000-8000-000000000010',c.id,w.id from public.crews c cross join public.workers w order by c.id,w.id limit 500;
select pg_temp.ok((select sum(jsonb_array_length(x->'workerIds'))=500 from jsonb_array_elements(pg_temp.snapshot()->'crews') x),'all500 memberships');
insert into public.crew_members select 'a2230000-0000-4000-8000-000000000010',c.id,w.id from public.crews c cross join public.workers w where not exists(select 1 from public.crew_members m where m.crew_id=c.id and m.worker_id=w.id) limit 1;
select pg_temp.reject('select pg_temp.snapshot()','54000');rollback to membership_max;
savepoint eligibility_max;
select pg_temp.seed_workers(100);select pg_temp.seed_services(11);
insert into public.service_worker_eligibility select 'a2230000-0000-4000-8000-000000000010',s.id,w.id,false from public.services s cross join public.workers w order by s.id,w.id limit 1000;
select pg_temp.ok(jsonb_array_length(pg_temp.snapshot()->'eligibility')=1000,'all1000 eligibility');
insert into public.service_worker_eligibility select 'a2230000-0000-4000-8000-000000000010',s.id,w.id,false from public.services s cross join public.workers w where not exists(select 1 from public.service_worker_eligibility e where e.service_id=s.id and e.worker_id=w.id) limit 1;
select pg_temp.reject('select pg_temp.snapshot()','54000');rollback to eligibility_max;
savepoint shift_max;
select pg_temp.seed_workers(1);
-- Trusted bulk snapshot fixtures avoid repeating the already-tested timezone write trigger1000times.
-- Only this named trigger is disabled inside this rollback-only test transaction.
alter table public.worker_shifts disable trigger worker_shift_zone;
insert into public.worker_shifts(id,tenant_id,worker_id,kind,starts_at,ends_at,source_time_zone,active) select gen_random_uuid(),'a2230000-0000-4000-8000-000000000010',(select id from public.workers),'blocked','2035-01-01T10:00Z','2035-01-01T11:00Z','UTC',false from generate_series(1,1000);
alter table public.worker_shifts enable trigger worker_shift_zone;
select pg_temp.ok(jsonb_array_length(pg_temp.snapshot()->'shifts')=1000,'all1000 blocked shifts');
insert into public.worker_shifts(id,tenant_id,worker_id,kind,starts_at,ends_at,source_time_zone) select gen_random_uuid(),'a2230000-0000-4000-8000-000000000010',id,'available','2035-01-01T10:00Z','2035-01-01T11:00Z','UTC' from public.workers;
select pg_temp.reject('select pg_temp.snapshot()','54000');rollback to shift_max;
savepoint service_text_max;
select pg_temp.seed_services(16,repeat('x',4096));select pg_temp.ok(jsonb_array_length(pg_temp.snapshot()->'services')=16,'65536service bytes');select pg_temp.seed_services(1);select pg_temp.reject('select pg_temp.snapshot()','54000');rollback to service_text_max;
savepoint raw_text_max;
select pg_temp.seed_workers(100);update public.workers set display_name=repeat(chr(128512),160);
select pg_temp.seed_crews(50);update public.crews set name=repeat(chr(128512),160);
select pg_temp.seed_services(8,repeat('x',4096));select pg_temp.seed_services(1,repeat('x',2304));
select pg_temp.ok(jsonb_array_length(pg_temp.snapshot()->'workers')=100,'131072combined raw bytes');
update public.services set name=name||'x' where length(name)=2304;select pg_temp.reject('select pg_temp.snapshot()','54000');rollback to raw_text_max;
-- Escaping expands serialized bytes without exceeding any raw-text/count cap.
savepoint serialized_max;
select pg_temp.seed_workers(100);update public.workers set display_name=repeat(chr(1),160);
select pg_temp.seed_crews(50);update public.crews set name=repeat(chr(1),160);
select pg_temp.seed_services(10);
insert into public.service_worker_eligibility select 'a2230000-0000-4000-8000-000000000010',s.id,w.id,false from public.services s cross join public.workers w;
alter table public.worker_shifts disable trigger worker_shift_zone;
insert into public.worker_shifts(id,tenant_id,worker_id,kind,starts_at,ends_at,source_time_zone,active) select gen_random_uuid(),'a2230000-0000-4000-8000-000000000010',(select id from public.workers order by id limit 1),'blocked','2035-01-01T10:00Z','2035-01-01T11:00Z','UTC',false from generate_series(1,1000);
alter table public.worker_shifts enable trigger worker_shift_zone;
select pg_temp.reject('select pg_temp.snapshot()','54000');
-- Same counts with ordinary labels fit; verify stable lexical ordering too.
update public.workers set display_name='Worker';update public.crews set name='Crew';
select pg_temp.ok(octet_length(pg_temp.snapshot()::text)<=524288,'complete combined snapshot fits');
select pg_temp.ok((select array_agg(x->>'id' order by ord)=array_agg(x->>'id' order by (x->>'id') collate "C") from jsonb_array_elements(pg_temp.snapshot()->'workers') with ordinality a(x,ord)),'workers lexical ordering');
select pg_temp.ok((select array_agg((x->>'serviceId')||(x->>'workerId') order by ord)=array_agg((x->>'serviceId')||(x->>'workerId') order by ((x->>'serviceId')||(x->>'workerId')) collate "C") from jsonb_array_elements(pg_temp.snapshot()->'eligibility') with ordinality a(x,ord)),'eligibility tuple ordering');
rollback to serialized_max;
select pg_temp.ok(not has_function_privilege('anon','public.owner_roster_snapshot(uuid,uuid)','EXECUTE') and not has_function_privilege('authenticated','public.owner_roster_snapshot(uuid,uuid)','EXECUTE') and has_function_privilege('service_role','public.owner_roster_snapshot(uuid,uuid)','EXECUTE'),'RPC ACL');
select pg_temp.ok(not has_table_privilege('service_role','public.worker_access','SELECT'),'private table ACL unchanged');
update public.tenants set status='suspended' where id='a2230000-0000-4000-8000-000000000010';select pg_temp.reject('select pg_temp.snapshot()','42501');
rollback;
\echo OWNER ROSTER SNAPSHOT SQL TESTS PASS
